     * U+6500 U+7400 instead, so a correct decode proves the byte order. */
    test('decodes a BOM-less charset=utf-16 body as big-endian', () async {
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      // UTF-16BE for "Pet", no BOM.
      final payload = <int>[
        0x00, 0x50, // P
        0x00, 0x65, // e
        0x00, 0x74, // t
      ];
      server.listen((request) {
        request.response
          ..statusCode = 200
          ..headers.set('Content-Type', 'text/plain; charset=utf-16')
          ..add(payload)
          ..close();
      });

      try {
        final client = DefaultApiClient();
        final resp = await client.sendRequest(
          'GET',
          'http://127.0.0.1:${server.port}/utf16-nobom',
          {},
          null,
        );
        expect(resp.statusCode, equals(200));
        expect(resp.body, equals('Pet'));
        // Prove the big-endian choice: the same bytes read little-endian
        // would not yield "Pet".
        expect(
          resp.body,
          isNot(equals(String.fromCharCodes(<int>[0x5000, 0x6500, 0x7400]))),
        );
      } finally {
        await server.close();
      }
    });

    /* dart-charset-utf16-mojibake (lenient fallback): an unrecognised
     * charset with non-UTF-8 bytes must fall back to a lossy UTF-8
     * decode rather than throwing a FormatException. */
    test('falls back leniently for an unknown charset, never throws', () async {
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      server.listen((request) {
        request.response
          ..statusCode = 200
          ..headers.set('Content-Type', 'text/plain; charset=shift_jis')
          ..add(<int>[0x82, 0xA0]) // invalid UTF-8 bytes
          ..close();
      });

      try {
        final client = DefaultApiClient();
        final resp = await client.sendRequest(
          'GET',
          'http://127.0.0.1:${server.port}/sjis',
          {},
          null,
        );
        // Must not throw; lenient decode yields replacement chars.
        expect(resp.statusCode, equals(200));
        expect(resp.body, isNotNull);
      } finally {
        await server.close();
      }
    });

    /* response-body-read-error-not-wrapped: a connection that drops
     * AFTER the response headers (here: a declared Content-Length that
     * is never fully delivered before the socket is destroyed) must
     * surface as the uniform ApiError, not a raw dart:io exception. */
    test('wraps a body-read failure in ApiError', () async {
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      server.listen((request) async {
        // Announce 100 bytes, send only a few, then kill the socket so
        // the body read fails mid-stream.
        final socket = await request.response.detachSocket();
        socket.write(
          'HTTP/1.1 200 OK\r\n'
          'Content-Type: text/plain\r\n'
          'Content-Length: 100\r\n'
          '\r\n'
          'short',
        );
        await socket.flush();
        await socket.close();
        socket.destroy();
      });

      try {
        final client = DefaultApiClient();
        await expectLater(
          client.sendRequest(
            'GET',
            'http://127.0.0.1:${server.port}/truncated',
            {},
            null,
          ),
          throwsA(isA<ApiError>().having((e) => e.statusCode, 'statusCode', 0)),
        );
      } finally {
        await server.close();
      }
    });

    test('joins multi-value response headers', () async {
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      server.listen((request) {
        request.response
          ..statusCode = 200
          ..headers.add('X-Custom-Value', 'val1')
          ..headers.add('X-Custom-Value', 'val2')
          ..write('ok')
          ..close();
      });

      try {
        final client = DefaultApiClient();
        final resp = await client.sendRequest(
          'GET',
          'http://localhost:${server.port}/multi-header',
          {},
          null,
        );
        expect(resp.statusCode, equals(200));
        final headerEntry = resp.headers.entries.firstWhere(
          (e) => e.key.toLowerCase() == 'x-custom-value',
          orElse: () => const MapEntry('', ''),
        );
        expect(headerEntry.value, contains('val1'));
        expect(headerEntry.value, contains('val2'));
      } finally {
        await server.close();
      }
    });

    /* T-CA-ERRTYPE: an explicitly configured CA certificate path that cannot
     * be read or parsed must fail fast at construction with the SDK's typed
     * ApiError (statusCode 0) — NOT a raw dart:io FileSystemException /
     * TlsException. A caller guarding construction with `on ApiError` would
     * otherwise miss this security-relevant TLS-pinning misconfiguration. */
    test('non-existent caCertPath throws ApiError at construction', () {
      final transport = TransportOptionsBuilder()
          .caCertPath('/nonexistent/ca.pem')
          .build();
      expect(
        () => DefaultApiClient(transportOptions: transport),
        throwsA(
          isA<ApiError>()
              .having((e) => e.statusCode, 'statusCode', 0)
              .having((e) => e.message, 'message', contains('CA certificate'))
              .having((e) => e.underlyingError, 'underlyingError', isNotNull),
        ),
      );
      // It must NOT leak the raw dart:io exception type.
      expect(
        () => DefaultApiClient(transportOptions: transport),
        throwsA(isNot(isA<FileSystemException>())),
      );
    });

    test('garbage-PEM caCertPath throws ApiError at construction', () async {
      final dir = await Directory.systemTemp.createTemp('ca_cert_test');
      final badPem = File('${dir.path}/garbage.pem');
      await badPem.writeAsString(
        '-----BEGIN CERTIFICATE-----\n'
        'this is not valid base64 PEM content\n'
        '-----END CERTIFICATE-----\n',
      );
      try {
        final transport = TransportOptionsBuilder()
            .caCertPath(badPem.path)
            .build();
        expect(
          () => DefaultApiClient(transportOptions: transport),
          throwsA(
            isA<ApiError>()
                .having((e) => e.statusCode, 'statusCode', 0)
                .having((e) => e.message, 'message', contains('CA certificate'))
                .having((e) => e.underlyingError, 'underlyingError', isNotNull),
          ),
        );
        // It must NOT leak the raw dart:io TlsException type.
        expect(
          () => DefaultApiClient(transportOptions: transport),
          throwsA(isNot(isA<TlsException>())),
        );
      } finally {
        await dir.delete(recursive: true);
      }
    });

    // -- Gap BI / Gap F: multipart filename directive + validation --

    test('non-ASCII multipart filename emits RFC 5987 filename*', () {
      final directive = buildFilenameDirective('日本.pdf');
      expect(directive, contains("filename*=UTF-8''"));
      expect(directive, contains('%E6%97%A5%E6%9C%AC'));
      expect(directive, startsWith('filename="'));
    });

    test('ASCII-only multipart filename omits filename*', () {
      final directive = buildFilenameDirective('pet.png');
      expect(directive, equals('filename="pet.png"'));
      expect(directive, isNot(contains('filename*=')));
    });

    test('backslash-escapes quotes in multipart filename', () {
      final directive = buildFilenameDirective('a"b.txt');
      expect(directive, contains('a\\"b.txt'));
    });

    test('rejects multipart filename containing CRLF', () {
      expect(
        () => validateMultipartFilename('a\rb.pdf'),
        throwsA(isA<ArgumentError>()),
      );
      expect(
        () => validateMultipartFilename('a\nb.pdf'),
        throwsA(isA<ArgumentError>()),
      );
      expect(
        () => validateMultipartFilename('a\r\nb.pdf'),
        throwsA(isA<ArgumentError>()),
      );
      // ASCII filename does not throw.
      validateMultipartFilename('pet.png');
    });

    test('rejects multipart filename containing NUL', () {
      expect(
        () => validateMultipartFilename('a\x00b.pdf'),
        throwsA(isA<ArgumentError>()),
      );
    });

    // -- Gap J: per-part MIME sniffing from the filename extension --

    /* The multipart body now carries the file part's raw bytes (not a
     * stringified byte list), so the request body is binary and must be read
     * with a byte-preserving decoder. `latin1` maps each byte 1:1 to a code
     * unit and never throws on non-UTF-8 bytes (e.g. the 0x89 PNG signature),
     * which lets the test inspect the ASCII Content-Disposition / Content-Type
     * header lines while the binary part content passes through intact. */
    Future<String> readBodyAsLatin1(HttpRequest request) async {
      final bytes = <int>[];
      await for (final chunk in request) {
        bytes.addAll(chunk);
      }
      return latin1.decode(bytes).toLowerCase();
    }

    test('multipart .png field sets image/png Content-Type', () async {
      String body = '';
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      server.listen((request) async {
        body = await readBodyAsLatin1(request);
        request.response
          ..statusCode = 200
          ..close();
      });

      try {
        final client = DefaultApiClient();
        await client.sendRequest(
          'POST',
          'http://127.0.0.1:${server.port}/upload',
          {},
          {
            'image.png': Uint8List.fromList([0x89, 0x50, 0x4E, 0x47]),
          },
        );
        expect(body, contains('content-type: image/png'));
      } finally {
        await server.close();
      }
    });

    test('multipart .pdf field sets application/pdf Content-Type', () async {
      String body = '';
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      server.listen((request) async {
        body = await readBodyAsLatin1(request);
        request.response
          ..statusCode = 200
          ..close();
      });

      try {
        final client = DefaultApiClient();
        await client.sendRequest(
          'POST',
          'http://127.0.0.1:${server.port}/upload',
          {},
          {
            'doc.pdf': Uint8List.fromList([0x25, 0x50, 0x44, 0x46]),
          },
        );
        expect(body, contains('content-type: application/pdf'));
      } finally {
        await server.close();
      }
    });

    test(
      'multipart field without extension defaults to octet-stream',
      () async {
        String body = '';
        final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
        server.listen((request) async {
          body = await readBodyAsLatin1(request);
          request.response
            ..statusCode = 200
            ..close();
        });

        try {
          final client = DefaultApiClient();
          await client.sendRequest(
            'POST',
            'http://127.0.0.1:${server.port}/upload',
            {},
            {
              'blob': Uint8List.fromList([0x00, 0x01, 0x02]),
            },
          );
          expect(body, contains('content-type: application/octet-stream'));
        } finally {
          await server.close();
        }
      },
    );

    // -- Gap 3.2: noRedirect controls redirect following --

    test('noRedirect: true returns raw 308 without following', () async {
      var targetHits = 0;
      final target = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      target.listen((request) {
        targetHits++;
        request.response
          ..statusCode = 200
          ..close();
      });

      final source = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      source.listen((request) {
        request.response
          ..statusCode = 308
          ..headers.set('Location', 'http://127.0.0.1:${target.port}/landed')
          ..close();
      });

      try {
        final client = DefaultApiClient();
        final resp = await client.sendRequest(
          'POST',
          'http://localhost:${source.port}/token',
          {},
          null,
          noRedirect: true,
        );
        expect(resp.statusCode, equals(308));
        expect(
          targetHits,
          equals(0),
          reason: 'noRedirect must suppress the redirect follow',
        );
      } finally {
        await source.close();
        await target.close();
      }
    });

    test('noRedirect: false follows redirects normally', () async {
      var targetHits = 0;
      final target = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      target.listen((request) {
        targetHits++;
        request.response
          ..statusCode = 200
          ..write('ok')
          ..close();
      });

      final source = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      source.listen((request) {
        request.response
          ..statusCode = 307
          ..headers.set('Location', 'http://127.0.0.1:${target.port}/landed')
          ..close();
      });

      try {
        final client = DefaultApiClient();
        final resp = await client.sendRequest(
          'GET',
          'http://localhost:${source.port}/start',
          {},
          null,
          noRedirect: false,
        );
        expect(resp.statusCode, equals(200));
        expect(
          targetHits,
          equals(1),
          reason: 'the redirect must be followed to the target',
        );
      } finally {
        await source.close();
        await target.close();
      }
    });
  });
}
